function searchRange(nums: number[], target: number): number[] {
  // lower bound: первый индекс i, где nums[i] >= x (или nums.length, если такого нет)
  const lowerBound = (x: number): number => {
    let lo = 0;
    let hi = nums.length; // полуинтервал [lo, hi)
    while (lo < hi) {
      const mid = lo + ((hi - lo) >> 1);
      if (nums[mid] < x) {
        lo = mid + 1; // граница правее mid
      } else {
        hi = mid; // mid подходит, но граница может быть левее
      }
    }
    return lo;
  };

  // Первое вхождение — первый элемент >= target
  const start = lowerBound(target);
  if (start === nums.length || nums[start] !== target) return [-1, -1];

  // Последнее вхождение — элемент перед первым, который > target.
  // Числа целые, поэтому «> target» — это «>= target + 1»
  const end = lowerBound(target + 1) - 1;

  return [start, end];
}

// Время: O(log n) — два бинарных поиска
// Память: O(1)
